\begin{aligned}
\frac12m^2\int\mathrm d^{n-1}x\,\phi^2
=\frac12m^2\int\mathrm d^{n-1}k\left(\frac{1}{2\omega}\right)
\Big[&
\hat a_{\mathbf k}\hat a_{-\mathbf k}e^{-2i\omega t}
+\hat a_{\mathbf k}^\dagger\hat a_{\mathbf k}\\
